package main

import (
	"bufio"
	"fmt"
	"os"
)

func nCr(n, k int64) int64 {
	if k > n-k {
		k = n - k
	}
	res := int64(1)
	for i := int64(0); i < k; i++ {
		res = res * (n - i)
		res = res / (i + 1)
	}
	return res
}

func modPow(base, exp, mod int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m, k int64
	fmt.Fscan(in, &n, &m, &k)

	mod := int64(998244353)

	selection := nCr(n-1, k) % mod
	colorsWays := (m % mod) * modPow(m-1, k, mod) % mod

	totalWays := (colorsWays * selection) % mod
	fmt.Println(totalWays)
}

